def flav_field(label,c,w,y,flavours,kind='F',copies=1):
    f=field(label,c=c,w=w,q=y,kind=kind,copies=copies)
    for factor,rep in zip(['flQ','flU','flD'],flavours):f['gauge_representations'][factor]=weight(rep)
    return f
one=[1,0];sing=[0,0];anti=[0,1]
flav_fields=[flav_field('QL',one,1,'1/6',[one,sing,sing]),flav_field('UR',one,0,'2/3',[sing,one,sing],'R'),flav_field('DR',one,0,'-1/3',[sing,sing,one],'R'),flav_field('PsiuR',one,0,'2/3',[one,sing,sing],'R'),flav_field('PsidR',one,0,'-1/3',[one,sing,sing],'R'),flav_field('Psiu',one,0,'2/3',[sing,one,sing]),flav_field('Psid',one,0,'-1/3',[sing,sing,one]),flav_field('L',sing,1,'-1/2',[sing,sing,sing],copies=3),flav_field('e^c',sing,0,'1',[sing,sing,sing],copies=3),flav_field('H',sing,1,'1/2',[sing,sing,sing],'S'),flav_field('Yu',sing,0,'0',[anti,one,sing],'S'),flav_field('Yd',sing,0,'0',[anti,sing,one],'S')]
flav=spectrum('P31','Gauged SU3-cubed quark flavour',flav_factors,flav_fields)
flav_ab=deepcopy(flav);flav_ab['name']='SU3-cubed flavour with two Abelian generators'
flav_ab['gauge_factors'] += [{'id':'uRnumber','family':'U1','rank':1},{'id':'dRnumber','family':'U1','rank':1}]
for f in flav_ab['matter']:
    f['gauge_representations']['uRnumber']=charge(1 if f['label'] in {'UR','Psiu','Yu'} else 0)
    f['gauge_representations']['dRnumber']=charge(1 if f['label'] in {'DR','Psid','Yd'} else 0)
